import json
b = json.load(open('baseline-packages.json'))
a = json.load(open('after-cpm-packages.json'))

def extract(data):
    result = {}
    for p in data['projects']:
        name = p['path'].split('/')[-1]
        for fw in p['frameworks']:
            for pkg in fw.get('topLevelPackages', []):
                result[(name, pkg['id'])] = pkg['resolvedVersion']
    return result

before = extract(b)
after = extract(a)
if before == after:
    print('Version-neutral: all packages resolve identically.')
else:
    for k in sorted(set(list(before.keys()) + list(after.keys()))):
        bv = before.get(k, 'MISSING')
        av = after.get(k, 'MISSING')
        if bv != av:
            print(f'CHANGED: {k} {bv} -> {av}')
"

